from django.conf import settings
from django.db import models

# Public ids ("key") are generated by the app so it can update its screen right
# away and send the same id to the server. Every lookup is still scoped to the
# signed-in landlord or tenant, so guessing a key gives no access.


class AppState(models.Model):
    """Per-user onboarding flags the app needs between sessions."""

    user = models.OneToOneField(settings.AUTH_USER_MODEL, on_delete=models.CASCADE,
                                related_name='lease_state')
    landlord_consented = models.BooleanField(default=False)
    tenant_consented = models.BooleanField(default=False)
    tenant_welcomed = models.BooleanField(default=True)
    baseline_reviewed = models.BooleanField(default=False)

    @classmethod
    def for_user(cls, user):
        state, _ = cls.objects.get_or_create(user=user)
        return state


class Property(models.Model):
    key = models.CharField(max_length=64, unique=True)
    owner = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.CASCADE,
                              related_name='properties')
    street = models.CharField(max_length=200)
    city = models.CharField(max_length=200, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)


class Unit(models.Model):
    key = models.CharField(max_length=64, unique=True)
    property = models.ForeignKey(Property, on_delete=models.CASCADE, related_name='units')
    name = models.CharField(max_length=40)
    bedrooms = models.CharField(max_length=4, blank=True)
    bathrooms = models.CharField(max_length=4, blank=True)
    areas = models.JSONField(default=list)
    baseline_recorded_on = models.DateField(null=True, blank=True)
    # Landlord's move-in notes per area, e.g. an existing scratch. Sent to Gemini as known issues.
    baseline_notes = models.JSONField(default=dict)
    created_at = models.DateTimeField(auto_now_add=True)


class TenantLink(models.Model):
    class Status(models.TextChoices):
        PENDING = 'pending'
        JOINED = 'joined'
        DECLINED = 'declined'

    unit = models.OneToOneField(Unit, on_delete=models.CASCADE, related_name='tenant_link')
    email = models.EmailField()
    name = models.CharField(max_length=150, blank=True)
    status = models.CharField(max_length=8, choices=Status.choices, default=Status.PENDING)
    tenant = models.ForeignKey(settings.AUTH_USER_MODEL, null=True, blank=True,
                               on_delete=models.SET_NULL, related_name='tenancies')
    invited_on = models.DateField()
    joined_on = models.DateField(null=True, blank=True)
    declined_on = models.DateField(null=True, blank=True)


class Inspection(models.Model):
    class Kind(models.TextChoices):
        REMOTE = 'remote'
        IN_PERSON = 'inperson'

    class Status(models.TextChoices):
        SCHEDULED = 'scheduled'
        AWAITING_TIMES = 'awaiting-times'
        TIMES_SENT = 'times-sent'
        TIMES_DECLINED = 'times-declined'
        CONFIRMED = 'confirmed'
        SUBMITTED = 'submitted'

    class AIStatus(models.TextChoices):
        NONE = ''
        PENDING = 'pending'
        DONE = 'done'
        ERROR = 'error'

    key = models.CharField(max_length=64, unique=True)
    unit = models.ForeignKey(Unit, on_delete=models.CASCADE, related_name='inspections')
    kind = models.CharField(max_length=8, choices=Kind.choices)
    areas = models.JSONField(default=list)
    status = models.CharField(max_length=16, choices=Status.choices)
    due_date = models.CharField(max_length=10, blank=True)  # ISO yyyy-mm-dd
    slots = models.JSONField(default=list)  # [{id, date, time}]
    tenant_slots = models.JSONField(default=list)
    confirmed_slot = models.CharField(max_length=64, blank=True)
    created_on = models.DateField()
    submitted_on = models.DateField(null=True, blank=True)
    ai_status = models.CharField(max_length=8, choices=AIStatus.choices, blank=True, default='')
    tenant_notes = models.JSONField(default=dict)  # {area: note}
    # {area: InspectionResult dict} or {area: {"error": "..."}}
    ai_results = models.JSONField(default=dict)
    created_at = models.DateTimeField(auto_now_add=True)


class Photo(models.Model):
    class Kind(models.TextChoices):
        BASELINE = 'baseline'
        MOVE_IN = 'move_in'
        INSPECTION = 'inspection'

    unit = models.ForeignKey(Unit, on_delete=models.CASCADE, related_name='photos')
    inspection = models.ForeignKey(Inspection, null=True, blank=True,
                                   on_delete=models.CASCADE, related_name='photos')
    kind = models.CharField(max_length=10, choices=Kind.choices)
    area = models.CharField(max_length=60)
    url = models.URLField(max_length=500)
    public_id = models.CharField(max_length=255, blank=True)
    uploaded_by = models.ForeignKey(settings.AUTH_USER_MODEL, null=True,
                                    on_delete=models.SET_NULL, related_name='+')
    created_at = models.DateTimeField(auto_now_add=True)


class Activity(models.Model):
    landlord = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.CASCADE,
                                 related_name='lease_activity')
    title = models.CharField(max_length=200)
    detail = models.CharField(max_length=200, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)
